import builtins, time
def frames(n):
    for _ in range(n):
        app.update(True)
def tick():
    return app.actions.run('timeline.status')['tick']
def until_tick(n):
    deadline = time.monotonic() + 60.0
    while tick() != n:
        assert time.monotonic() < deadline, (tick(), n)
        app.update(True)
    frames(3)
def step(n):
    t = tick()
    app.actions.run('sim.step', steps=n)
    until_tick(t + n)
def reset():
    app.actions.run('sim.reset')
    until_tick(0)
def fails(action, text, **args):
    from nuka.editor.app import ActionError
    try:
        app.actions.run(action, **args)
    except ActionError as e:
        assert text in str(e), (action, args, str(e))
    else:
        raise AssertionError((action, args))
def ref(keys, t):
    if t <= keys[0]['time']:
        return keys[0]['value']
    if t >= keys[-1]['time']:
        return keys[-1]['value']
    i = max(i for i, k in enumerate(keys) if k['time'] <= t)
    a, b = keys[i], keys[i + 1]
    h = b['time'] - a['time']
    s = (t - a['time']) / h
    r = 1.0 - s
    if a['interp'] == 'step':
        return a['value']
    if a['interp'] == 'linear':
        return a['value'] + (b['value'] - a['value']) * s
    p1, p2 = a['value'] + a['out'] * h / 3.0, b['value'] - b['in'] * h / 3.0
    return r ** 3 * a['value'] + 3.0 * r * r * s * p1 + 3.0 * r * s * s * p2 + s ** 3 * b['value']
def tracks(clip=None):
    return {t['joint']: t['keys'] for t in app.clips.get(clip)['tracks']}
def check(times, clip=None):
    tr = tracks(clip)
    for t in times:
        got = app.clips.sample(t, clip=clip)['values']
        want = {j: ref(k, t) for j, k in tr.items()}
        assert got.keys() == want.keys() and all(abs(got[j] - want[j]) < 1e-5 for j in want), (t, got, want)
builtins.cl_frames, builtins.cl_tick, builtins.cl_step, builtins.cl_reset = frames, tick, step, reset
builtins.cl_fails, builtins.cl_ref, builtins.cl_tracks, builtins.cl_check = fails, ref, tracks, check
s = app.clips.list()
assert s['clips'] == [] and s['edited'] is None and s['playing'] is None and not s['open'] and not s['can_undo'], s
